 for(const tab of ['reports','cards','chat']){assert.equal(backAction(false,false,2,tab),'nested');assert.equal(backAction(false,false,3,tab),'nested');assert.equal(backAction(false,false,1,tab),'home');}
 assert.equal(backAction(false,false,1,'home'),'system');assert.equal(backAction(false,true,3,'reports'),'sheet');assert.equal(backAction(true,true,3,'reports'),'block');assert.equal(backAction(true,false,1,'home'),'block');
